233	// renderer runs one tool in the repository, the way every other tool runs:
234	// in the target for a binary; for an image, with the scope's mount read-only
235	// at /scan and the target inside it as the working directory.
236	func renderer(scope renderScope, tool ToolSpec, defaultImage, binary string, args ...string) toolCmd {
237		// helm gets them on lint and on template alike: only the flags the two
238		// share (--values, --set…) make sense there.
239		args = afterSubcommand(args, tool.Args)
240		if tool.Source != ToolSourceContainer {
241			name := tool.Binary
242			if name == "" {
243				name = binary
244			}
245			cmd := toolCmd{Name: name, Args: args, Dir: scope.target}
246			if scope.offline {
247				cmd.Env = offlineEnviron(os.Environ())
248			}
249			return cmd
250		}
251		return containerRun{
252			Flags:   []string{"-v", scope.mount + ":" + containerScanPath + ":ro", "-w", scope.workdir()},
253			Image:   orDefault(tool.Image, defaultImage),
254			Argv:    args,
255			Offline: scope.offline,
256		}.cmd()
257	}
258	
259	func orDefault(v, def string) string {
260		if v == "" {
261			return def
262		}
263		return v
264	}
265	
266	// renderRepro is the Repro line of a renderer run on target (a chart or an
267	// overlay directory), run from the scanned directory like the scan did. The
268	// user's arguments are left out: they may hold a secret (--set password=REDACTED
269	func renderRepro(tool ToolSpec, name, sub, target string) (string, ToolSource) {
270		return localRepro(tool, name, []string{sub}, target)
271	}
272	
273	func helmArgs(scope renderScope, chart string, tool ToolSpec, sub string) toolCmd {
274		return renderer(scope, tool, DefaultHelmImage, "helm", sub, asPathArg(chart))
275	}
276	
277	func kustomizeArgs(scope renderScope, dir string, tool ToolSpec) toolCmd {
278		return renderer(scope, tool, DefaultKustomizeImage, "kustomize", "build", asPathArg(dir))
279	}
280	
281	// asPathArg is dir as a positional argument of helm or kustomize. The folder's
282	// name comes from the repository being scanned, and two kinds of name are not
283	// read as the local folder it is (DEVDESK-763): one that starts with "-"
284	// (--load-restrictor=LoadRestrictionsNone, -x) is read as an option, and
285	// kustomize reads an ordinary one such as github.com/org/repo or
286	// git@host:o/r as a remote git base and runs git fetch even when the folder
287	// exists. "./" makes every relative folder a local path whatever the tool and
288	// wherever the user's own arguments land. "." and an absolute path already are
289	// one, and a name that already starts with "./" is left alone. Only the
290	// argument is changed: the findings, their steps and the Repro keep the
291	// folder's own name.
292	func asPathArg(dir string) string {
293		if dir == "." || strings.HasPrefix(dir, "./") || filepath.IsAbs(dir) || strings.HasPrefix(dir, "/") {
294			return dir
295		}
296		return "./" + dir
297	}
