586	// How to fix a chart or an overlay that does not render, in the renderer's own
587	// terms.
588	const (
589		helmRenderResolution = "Render it locally with helm template and fix what it reports; " +
590			"a chart's dependencies must be vendored in charts/ or fetched with helm dependency build."
591		// remoteBlockedResolution is for an overlay whose remote base was refused
592		// because the render runs with the network cut (DEVDESK-767).
593		remoteBlockedResolution = "The overlay names a remote base (a git URL or an https resource) and DevDesk " +
594			"renders a repository it does not trust with the network cut. Copy the base into the repository " +
595			"and reference it by a relative path, or, for a repository you trust, set " +
596			"scan.tools.kustomize.allow_remote_bases: true."
597		kustomizeRenderResolution = "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports."
598		// kustomize's load restrictor (LoadRestrictionsRootOnly, its default)
599		// refuses a file outside the kustomization's directory, with this message.
600		// The flag is not reserved (ToolKustomize.ReservedArgs) and lands after
601		// `build` (afterSubcommand), where kustomize accepts it.
602		loadRestrictorResolution = "kustomize refuses by default a file outside the overlay directory " +
603			"(same as kubectl apply -k). Reference a directory with its own kustomization instead, " +
604			"or, if your deployment tool allows it, set " +
605			"scan.tools.kustomize.args: [--load-restrictor=LoadRestrictionsNone]."
606	)
607	
608	// mountResolution is added for a kustomize image that could not find a path:
609	// the container sees only what DevDesk mounts (renderScope), and DevDesk does
610	// not walk the repository to tell a hidden reference from a broken one.
611	// ToolConfig's `source` key takes auto, binary or image.
612	const mountResolution = "If this reference points outside the directory DevDesk mounts into the container " +
613		"(the scanned directory, or its git repository when it has one), scan the enclosing directory, " +
614		"or set scan.tools.kustomize.source: binary (the binary sees the whole file system)."
615	
616	// renderResolution picks the advice for a render failure from the renderer,
617	// where it ran and what it printed.
618	func renderResolution(source string, from ToolSource, detail string) string {
619		if source != SourceKustomize {
620			return helmRenderResolution
621		}
622		advice := kustomizeRenderResolution
623		if isLoadRestrictor(detail) {
624			advice = loadRestrictorResolution
625		}
626		if from == ToolSourceContainer &&
627			(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
628			advice += " " + mountResolution
629		}
630		return advice
631	}
632	
633	// helmOrigins maps each rendered resource, by kind and name, to the template
634	// it came from, relative to the repository. helm names the template under the
635	// chart's own name, which need not be its directory's.
636	func helmOrigins(rendered []byte, chart string) map[string]string {
637		origins := map[string]string{}
638		for _, doc := range splitYAMLDocuments(rendered) {
639			var source string
640			for _, line := range strings.Split(doc, "\n") {
641				if m := helmSourceLine.FindStringSubmatch(line); m != nil {
642					source = m[1]
643					break
644				}
645			}
646			if source == "" {
647				continue
648			}
649			var meta struct {
650				Kind     string `yaml:"kind"`
651				Metadata struct {
652					Name string `yaml:"name"`
653				} `yaml:"metadata"`
654			}
655			if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
656				continue
657			}
658			key := meta.Kind + "/" + meta.Metadata.Name
659			if _, seen := origins[key]; seen {
660				continue
661			}
662			_, rest, _ := strings.Cut(source, "/")
663			origins[key] = path.Join(chart, rest)
664		}
665		return origins
666	}
667	
668	// splitYAMLDocuments splits a multi-document stream on its `---` separators.
669	func splitYAMLDocuments(stream []byte) []string {
670		var docs []string
671		var cur strings.Builder
672		r := bufio.NewReader(bytes.NewReader(stream))
673		for {
674			line, err := r.ReadString('\n')
675			if strings.TrimRight(line, "\r\n") == "---" {
676				docs = append(docs, cur.String())
677				cur.Reset()
678			} else {
679				cur.WriteString(line)
680			}
681			if errors.Is(err, io.EOF) || err != nil {
682				break
683			}
684		}
685		return append(docs, cur.String())

140	// filesystem root nor the home directory nor anything above it, and it holds
141	// the repository's .git itself (gitDirIsHere). Anything else, an unknown home
142	// included, keeps the target alone.
143	func widerScope(target, top string) (renderScope, bool) {
144		if top == "" || !filepath.IsAbs(top) {
145			return renderScope{}, false
146		}
147		root, err := filepath.EvalSymlinks(top)
148		if err != nil {
149			return renderScope{}, false
150		}
151		real, err := filepath.EvalSymlinks(target)
152		if err != nil {
153			return renderScope{}, false
154		}
155		rel, err := filepath.Rel(root, real)
156		if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
157			return renderScope{}, false
158		}
159		if filepath.Dir(root) == root {
160			return renderScope{}, false
161		}
162		home, err := userHomeDir()
163		if err != nil || home == "" {
164			return renderScope{}, false
165		}
166		if h, err := filepath.EvalSymlinks(home); err == nil {
167			home = h
168		}
169		if r, err := filepath.Rel(root, filepath.Clean(home)); err == nil &&
170			(r == "." || (r != ".." && !strings.HasPrefix(r, ".."+string(filepath.Separator)))) {
171			return renderScope{}, false
172		}
173		if !gitDirIsHere(root) {
174			return renderScope{}, false
175		}
176		return renderScope{target: target, mount: root, rel: filepath.ToSlash(rel)}, true
177	}
178	
179	// maxGitFile bounds what is read of a .git file or a worktree's gitdir file:
180	// one line, a path.
181	const maxGitFile = 4096
182	
183	// gitDirIsHere reports whether root holds its repository's .git: a directory,
184	// or the file of a linked worktree ("gitdir: <dir>") whose git directory names
185	// root's .git back in its own gitdir file. A symlink, a file that says
186	// anything else, or a git directory that does not point back is refused: git
187	// was then told where the work tree is, rather than finding it.
188	func gitDirIsHere(root string) bool {
189		dotGit := filepath.Join(root, ".git")
190		info, err := os.Lstat(dotGit)
191		if err != nil {
192			return false
193		}
194		if info.IsDir() {
195			return true
196		}
197		if !info.Mode().IsRegular() {
198			return false
199		}
200		line, ok := readGitFile(dotGit)
201		gitDir, found := strings.CutPrefix(line, "gitdir: ")
202		if !ok || !found {
203			return false
204		}
205		if !filepath.IsAbs(gitDir) {
206			gitDir = filepath.Join(root, gitDir)
207		}
208		back, ok := readGitFile(filepath.Join(gitDir, "gitdir"))
209		if !ok {
210			return false
211		}
212		if !filepath.IsAbs(back) {
213			back = filepath.Join(gitDir, back)
214		}
215		a, errA := filepath.EvalSymlinks(back)
216		b, errB := filepath.EvalSymlinks(dotGit)
217		return errA == nil && errB == nil && a == b
218	}
219	
220	// readGitFile reads the one line of a small regular file.
221	func readGitFile(p string) (string, bool) {
222		info, err := os.Lstat(p)
223		if err != nil || !info.Mode().IsRegular() || info.Size() > maxGitFile {
224			return "", false
225		}
226		data, err := os.ReadFile(p) //nolint:gosec // a .git file of the repository being scanned
227		if err != nil {
228			return "", false
229		}
230		return strings.TrimSpace(string(data)), true
231	}
