331	// renderCharts lints, renders and validates each chart. Without helm, every
332	// chart is reported as not rendered.
333	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
334		tool := v.opts.Helm
335		for _, chart := range charts {
336			if !available(tool) {
337				v.report.Unrendered = append(v.report.Unrendered, chart)
338				continue
339			}
340			// helm reads no remote base, so it never has the network.
341			scope := v.scope.cut()
342			lint := helmLint(ctx, scope, chart, tool)
343			v.report.Findings = append(v.report.Findings, lint...)
344	
345			cmd := helmArgs(scope, chart, tool, "template")
346			log.Printf("Running: %s", cmd.Loggable())
347			rendered, err := runner.Run(ctx, cmd, nil)
348			if err != nil {
349				if ctx.Err() != nil {
350					return ctx.Err()
351				}
352				// helm lint renders the chart too, so a chart that does not
353				// render has usually been reported by it already, with more to
354				// say. The render failure is the fallback, not a second copy.
355				if !hasError(lint) {
356					repro, from := renderRepro(tool, "helm", "template", chart)
357					v.report.Findings = append(v.report.Findings,
358						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", from,
359							renderSteps(SourceHelm, chart, from, failureDetail(err), false), repro, err))
360				}
361				continue
362			}
363			origins := helmOrigins(rendered, chart)
364			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
365				if file, ok := origins[kind+"/"+name]; ok {
366					return file
367				}
368				return chart
369			})
370			if err != nil {
371				return fmt.Errorf("chart %s: %w", chart, err)
372			}
373		}
374		return nil
375	}
