529	func helmLintFinding(chart, file string, severity SeverityLevel, msg string) Finding {
530		return Finding{
531			Steps:       helmLintSteps(file, chart),
532			ID:          HelmLintID,
533			Title:       msg,
534			Description: "helm lint reported this about the chart.",
535			Message:     msg,
536			Severity:    severity,
537			Source:      SourceHelm,
538			File:        file,
539			IaCType:     "helm",
540		}
541	}
