633	// helmOrigins maps each rendered resource, by kind and name, to the template
634	// it came from, relative to the repository. helm names the template under the
635	// chart's own name, which need not be its directory's.
636	func helmOrigins(rendered []byte, chart string) map[string]string {
637		origins := map[string]string{}
638		for _, doc := range splitYAMLDocuments(rendered) {
639			var source string
640			for _, line := range strings.Split(doc, "\n") {
641				if m := helmSourceLine.FindStringSubmatch(line); m != nil {
642					source = m[1]
643					break
644				}
645			}
646			if source == "" {
647				continue
648			}
649			var meta struct {
650				Kind     string `yaml:"kind"`
651				Metadata struct {
652					Name string `yaml:"name"`
653				} `yaml:"metadata"`
654			}
655			if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
656				continue
657			}
658			key := meta.Kind + "/" + meta.Metadata.Name
659			if _, seen := origins[key]; seen {
660				continue
661			}
662			_, rest, _ := strings.Cut(source, "/")
663			origins[key] = path.Join(chart, rest)
664		}
665		return origins
666	}
667	
668	// splitYAMLDocuments splits a multi-document stream on its `---` separators.
669	func splitYAMLDocuments(stream []byte) []string {
670		var docs []string
671		var cur strings.Builder
672		r := bufio.NewReader(bytes.NewReader(stream))
673		for {
674			line, err := r.ReadString('\n')
675			if strings.TrimRight(line, "\r\n") == "---" {
676				docs = append(docs, cur.String())
677				cur.Reset()
678			} else {
679				cur.WriteString(line)
680			}
681			if errors.Is(err, io.EOF) || err != nil {
682				break
683			}
684		}
685		return append(docs, cur.String())

