135	// checkOffline fails unless env cuts the network of a native renderer: every
136	// name exactly once, with its dead value.
137	func checkOffline(t *testing.T, env []string) {
138		t.Helper()
139		const dead = "http://127.0.0.1:0"
140		want := map[string]string{
141			"GIT_ALLOW_PROTOCOL": "devdesk-none", "GIT_TERMINAL_PROMPT": "0",
142			"HTTP_PROXY": dead, "HTTPS_PROXY": dead, "http_proxy": dead, "https_proxy": dead,
143			"NO_PROXY": "", "no_proxy": "",
144			"LC_ALL": "C",
145		}
146		for name, value := range want {
147			if got := valuesOf(env, name); !slices.Equal(got, []string{value}) {
148				t.Errorf("%s = %q, want exactly [%q]", name, got, value)
149			}
150		}
151		for _, name := range []string{"ALL_PROXY", "all_proxy", "REQUEST_METHOD",
152			"SSH_AUTH_SOCK", "GIT_SSH", "GIT_SSH_COMMAND", "GIT_PROXY_COMMAND"} {
153			if got := valuesOf(env, name); len(got) != 0 {
154				t.Errorf("%s = %q, want it removed", name, got)
155			}
156		}
157	}
