159	func TestOfflineEnvironCutsTheNetworkAndKeepsTheRest(t *testing.T) {
160		tests := []struct {
161			name string
162			base []string
163			// kept are entries that must come out untouched, in this order.
164			kept []string
165		}{
166			{"no base", nil, nil},
167			{"nothing of the network in it", []string{"PATH=/usr/bin", "HOME=/home/u"},
168				[]string{"PATH=/usr/bin", "HOME=/home/u"}},
169			{"the host's proxy, both casings",
170				[]string{"PATH=/usr/bin",
171					"HTTP_PROXY=REDACTED", "http_proxy=REDACTED",
172					"HTTPS_PROXY=REDACTED", "https_proxy=REDACTED",
173					"ALL_PROXY=socks5://proxy.example:1080", "all_proxy=socks5://proxy.example:1080",
174					"NO_PROXY=.corp.example", "no_proxy=.corp.example", "LANG=fr_FR.UTF-8"},
175				[]string{"PATH=/usr/bin", "LANG=fr_FR.UTF-8"}},
176			{"a git protocol list, a locale and a request method",
177				[]string{"GIT_ALLOW_PROTOCOL=https:ssh", "LC_ALL=fr_FR.UTF-8", "REQUEST_METHOD=GET", "TERM=xterm"},
178				[]string{"TERM=xterm"}},
179			{"the user's ssh identity and git commands",
180				[]string{"HOME=/home/u", "SSH_AUTH_SOCK=/tmp/agent.1", "GIT_SSH=/usr/bin/ssh", "GIT_SSH_COMMAND=ssh -i /home/u/.ssh/id",
181					"GIT_PROXY_COMMAND=/usr/bin/nc", "GIT_TERMINAL_PROMPT=1", "XDG_RUNTIME_DIR=/run/user/1000"},
182				[]string{"HOME=/home/u", "XDG_RUNTIME_DIR=/run/user/1000"}},
183			{"values holding an equal sign", []string{"A=b=c", "SOME_SOCK=/tmp/x=y"},
184				[]string{"A=b=c", "SOME_SOCK=/tmp/x=y"}},
185			{"a variable that only looks like one of them", []string{"MY_HTTP_PROXY=x", "GIT_ALLOW_PROTOCOL_X=y", "LC_ALL_X=z", "PROXY=1"},
186				[]string{"MY_HTTP_PROXY=x", "GIT_ALLOW_PROTOCOL_X=y", "LC_ALL_X=z", "PROXY=1"}},
187		}
188		for _, tt := range tests {
189			t.Run(tt.name, func(t *testing.T) {
190				snapshot := slices.Clone(tt.base)
191	
192				got := offlineEnviron(tt.base)
193	
194				checkOffline(t, got)
195				var kept []string
196				for _, kv := range got {
197					if slices.Contains(tt.kept, kv) {
198						kept = append(kept, kv)
199					}
200				}
201				if !slices.Equal(kept, tt.kept) {
202					t.Errorf("the other variables = %q, want %q, in this order", kept, tt.kept)
203				}
204				if !slices.Equal(tt.base, snapshot) {
205					t.Errorf("the base was modified: %q, was %q", tt.base, snapshot)
206				}
207				for i := range got {
208					got[i] = "X=changed"
209				}
210				if !slices.Equal(tt.base, snapshot) {
211					t.Errorf("the result shares memory with the base: %q, was %q", tt.base, snapshot)
212				}
213			})
214		}
215	}
