588	// A remote base that was refused is a finding of its own: it says the network
589	// was cut, so that nobody reads "does not build" as a broken overlay, and it
590	// says how to get either outcome.
591	func TestABlockedRemoteBaseSaysTheNetworkWasCut(t *testing.T) {
592		cases := []struct {
593			name   string
594			deps   Report
595			stderr string
596			from   ToolSource
597		}{
598			{"ssh, native", kustomizeBinary(), sshBlockedStderr, ToolSourceBinary},
599			{"https git, native", kustomizeBinary(), httpsGitBlockedStderr, ToolSourceBinary},
600			{"https resource, native", kustomizeBinary(), urlBlockedStderr, ToolSourceBinary},
601			{"no such host, container", kustomizeImage(), containerNoSuchHostStderr, ToolSourceContainer},
602			{"could not resolve host, container", kustomizeImage(), containerCouldNotResolveStderr, ToolSourceContainer},
603			{"no git program, container", kustomizeImage(), containerNoGitStderr, ToolSourceContainer},
604		}
605		for _, c := range cases {
606			t.Run(c.name, func(t *testing.T) {
607				result := scanOverlay(t, c.deps, k8sSchemaFor("1.36.0"), c.stderr)
608	
609				f := renderFindingOf(t, result)
610				if !strings.HasPrefix(f.Title, remoteBlockedTitle) {
611					t.Errorf("title = %q, want it to start with %q", f.Title, remoteBlockedTitle)
612				}
613				if f.Severity != SeverityHigh || f.ID != K8sRenderID || f.Source != SourceKustomize || f.File != kustomizationDev+"/kustomization.yaml" {
614					t.Errorf("finding = %s %s %s in %s: only the wording changes", f.ID, f.Severity, f.Source, f.File)
615				}
616				if f.Message != strings.TrimSpace(c.stderr) {
617					t.Errorf("the tool's message was not kept whole:\n got %q\nwant %q", f.Message, strings.TrimSpace(c.stderr))
618				}
619				lower := strings.ToLower(f.Resolution)
620				for _, want := range []string{"network", "copy", "scan.tools.kustomize.allow_remote_bases: true"} {
621					if !strings.Contains(lower, want) {
622						t.Errorf("the Resolution lacks %q:\n%s", want, f.Resolution)
623					}
624				}
625				if f.Resolution == kustomizeRenderResolution {
626					t.Error("the Resolution is the generic one")
627				}
628				if len(f.Steps) == 0 || reflectEqualSteps(f.Steps, renderSteps(SourceKustomize, kustomizationDev, c.from, patchMistakeStderr, false)) {
629					t.Errorf("steps = %q, want steps of their own", f.Steps)
630				}
631				if f.RanFrom != c.from {
632					t.Errorf("RanFrom = %q, want %q", f.RanFrom, c.from)
633				}
634				// A copied `kustomize build` would run the refused fetch again, with the
635				// user's ssh agent and proxy, on a repository that is not trusted.
636				if f.Repro != "" {
637					t.Errorf("repro = %q, want none: it would run the refused fetch with the user's credentials", f.Repro)
638				}
639			})
640		}
641	}
