368	// networkNoneBefore reports whether the argv holds `--network none`, once,
369	// before the image: after the image it would be the tool's own argument.
370	func networkNoneBefore(args []string, image string) bool {
371		at := slices.Index(args, "--network")
372		img := slices.Index(args, image)
373		return slices.Index(args[at+1:], "--network") < 0 && at >= 0 && img > at+1 && args[at+1] == "none"
374	}
