723	// kustomizeWithGit is the kustomize on PATH when it is new enough to have
724	// printed the markers above (v5.8.3) and git is there to be refused. The test
725	// is skipped otherwise.
726	func kustomizeWithGit(t *testing.T) string {
727		t.Helper()
728		path, err := exec.LookPath("kustomize")
729		if err != nil {
730			t.Skip("no kustomize on PATH")
731		}
732		if _, err := exec.LookPath("git"); err != nil {
733			t.Skip("no git on PATH: kustomize reports a missing git, not a blocked transport")
734		}
735		out, err := exec.CommandContext(t.Context(), path, "version").Output() //nolint:gosec // the kustomize found on PATH, version only
736		if err != nil {
737			t.Skipf("kustomize version: %v", err)
738		}
739		m := regexp.MustCompile(`v?(\d+)\.(\d+)\.(\d+)`).FindStringSubmatch(string(out))
740		if m == nil {
741			t.Skipf("cannot read a version in %q", out)
742		}
743		var v [3]int
744		for i := range v {
745			v[i], _ = strconv.Atoi(m[i+1])
746		}
747		if slices.Compare(v[:], []int{5, 8, 3}) < 0 {
748			t.Skipf("kustomize %d.%d.%d is older than 5.8.3, whose messages these markers were measured on", v[0], v[1], v[2])
749		}
750		return path
751	}
