143	// With helm and kustomize, the chart and the overlay are validated once
144	// rendered, and every finding points back at a file of the repository — the
145	// template, or the overlay's kustomization — with no line, since a rendered
146	// line is no line of either.
147	func TestChartsAndOverlaysAreValidatedOnceRendered(t *testing.T) {
148		isolateHome(t)
149		repo := renderRepo(t)
150		renderRunner(t, stageReply{})
151	
152		result, _ := newScannerWithDeps(k8sSchemaFor("1.36.0"), renderingDeps()).
153			Scan(t.Context(), repo, TargetDirectory)
154	
155		if len(result.K8sUnrendered) != 0 {
156			t.Errorf("K8sUnrendered = %v, want none: both renderers were there", result.K8sUnrendered)
157		}
158		got := map[string]Finding{}
159		for _, f := range result.Findings {
160			got[f.Source+" "+f.File] = f
161		}
162		for key, dialect := range map[string]string{
163			"kubeconform charts/api/templates/deploy.yaml":    "helm",
164			"kubeconform k8s/overlays/prod/kustomization.yml": "kustomize",
165			"helm charts/api/templates/cm.yaml":               "helm",
166		} {
167			f, ok := got[key]
168			if !ok {
169				t.Errorf("no finding %q among %v", key, keys(got))
170				continue
171			}
172			if f.IaCType != dialect || f.Line != 0 {
173				t.Errorf("%s: type %q line %d, want %q and no line", key, f.IaCType, f.Line, dialect)
174			}
175		}
176		if len(result.Errors) != 0 {
177			t.Errorf("errors = %v, want none", result.Errors)
178		}
