204	func TestEveryStepsFunctionHasASample(t *testing.T) {
205		samples := stepSamples()
206		src := parseGuardSources(t, map[string]string{"steps.go": packageGuardSources(t)["steps.go"]})[0]
207		var discovered []string
208		for _, d := range src.file.Decls {
209			fd, ok := d.(*ast.FuncDecl)
210			if !ok || !strings.HasSuffix(fd.Name.Name, "Steps") {
211				continue
212			}
213			discovered = append(discovered, fd.Name.Name)
214			if _, ok := samples[fd.Name.Name]; !ok {
215				t.Errorf("%s writes steps and has no entry in stepSamples: add inputs that reach each of its branches", fd.Name.Name)
216			}
217		}
218		if len(discovered) < 4 {
219			t.Errorf("found %d *Steps functions in steps.go, expected at least 4: did the file move?", len(discovered))
220		}
221		for name := range samples {
222			if !slices.Contains(discovered, name) {
223				t.Errorf("stepSamples has %s, which steps.go no longer defines", name)
224			}
225		}
226	}
