68	// kubeconformArgs builds the invocation over files relative to target.
69	//
70	// The files are passed explicitly rather than the directory: kubeconform
71	// reports "missing 'kind' key" on every YAML file that is not a manifest —
72	// a CI configuration, a Helm values file — and k8s.Discover has already told
73	// the two apart. The tool runs in target so the file names it reports are the
74	// relative ones the findings carry.
75	func kubeconformArgs(target string, files []string, tool ToolSpec, opts KubeconformOptions) toolCmd {
76		docker := tool.Source == ToolSourceContainer
77		flags := kubeconformFlags(tool, opts)
78	
79		if !docker {
80			args := append(flags, afterOptions(nativePaths(files))...)
81			return toolCmd{Name: kubeconformBinary(tool), Args: args, Dir: target}
82		}
83	
84		engineArgs := []string{"-v", target + ":" + containerScanPath + ":ro"}
85		if opts.CacheDir != "" {
86			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
87		}
88		engineArgs = append(engineArgs, "-w", containerScanPath)
89		// Inside the container the paths are Linux ones, whatever the host is.
90		return containerRun{Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, afterOptions(files)...)}.cmd()
91	}
