126	// RunKubeconform finds the repository's manifests and validates them: the
127	// plain ones as files, the charts and overlays once rendered.
128	//
129	// The plain manifests are skipped when there are none rather than handed over
130	// as an empty list: kubeconform with no file argument reads stdin, and would
131	// wait there.
132	func RunKubeconform(ctx context.Context, target string, tool ToolSpec, opts KubeconformOptions, progressFn func(string)) (*KubeconformReport, error) {
133		layout, err := k8s.Discover(target)
134		if err != nil {
135			return nil, fmt.Errorf("listing manifests: %w", err)
136		}
137		if opts.CacheDir != "" {
138			if err := os.MkdirAll(opts.CacheDir, 0o755); err != nil {
139				// Validation still works without a cache; it downloads each time.
140				opts.CacheDir = ""
141			}
142		}
143		v := &k8sValidation{target: target, scope: targetOnly(target), kubeconform: tool, opts: opts,
144			report: &KubeconformReport{Validated: len(layout.Manifests)}}
145		// Only a renderer in a container needs more than the target mounted, and
146		// git is asked only when one is about to run.
147		if (len(layout.Charts) > 0 && opts.Helm.Source == ToolSourceContainer) ||
148			(len(layout.Kustomizations) > 0 && opts.Kustomize.Source == ToolSourceContainer) {
149			v.scope = resolveRenderScope(ctx, target)
150		}
151	
152		if len(layout.Manifests) > 0 {
153			if err := v.validateFiles(ctx, layout.Manifests, progressFn); err != nil {
154				return nil, err
155			}
156		}
157		if err := v.renderCharts(ctx, layout.Charts); err != nil {
158			return nil, err
159		}
160		if err := v.renderKustomizations(ctx, layout.Kustomizations); err != nil {
161			return nil, err
162		}
163		return v.report, nil
164	}
