185	// stampSchemaRepro records on each schema finding of a plain file where
186	// kubeconform ran and, when it ran on this machine, the command that checks that
187	// file again. DevDesk's own flags (-output json, -cache) are left out, and so are
188	// the user's arguments (scan.tools.kubeconform.args), which may hold a secret.
189	// K8S-API-REMOVED and K8S-PARSE carry neither (DEVDESK-752).
190	func (v *k8sValidation) stampSchemaRepro(findings []Finding) {
191		type reproLineFrom struct {
192			line string
193			from ToolSource
194		}
195		byFile := map[string]reproLineFrom{}
196		for i := range findings {
197			f := &findings[i]
198			if f.ID != K8sSchemaID {
199				continue
200			}
201			r, ok := byFile[f.File]
202			if !ok {
203				args := []string{"-strict"}
204				if v.opts.KubernetesVersion != "" {
205					args = append(args, "-kubernetes-version", v.opts.KubernetesVersion)
206				}
207				r.line, r.from = localRepro(v.kubeconform, "kubeconform", args, f.File)
208				byFile[f.File] = r
209			}
210			f.Repro, f.RanFrom = r.line, r.from
211		}
212	}
