68	// kubeconformArgs builds the invocation over files relative to target.
69	//
70	// The files are passed explicitly rather than the directory: kubeconform
71	// reports "missing 'kind' key" on every YAML file that is not a manifest —
72	// a CI configuration, a Helm values file — and k8s.Discover has already told
73	// the two apart. The tool runs in target so the file names it reports are the
74	// relative ones the findings carry.
75	func kubeconformArgs(target string, files []string, tool ToolSpec, opts KubeconformOptions) toolCmd {
76		docker := tool.Source == ToolSourceContainer
77		flags := kubeconformFlags(tool, opts)
78	
79		if !docker {
80			args := append(flags, afterOptions(nativePaths(files))...)
81			return toolCmd{Name: kubeconformBinary(tool), Args: args, Dir: target}
82		}
83	
84		engineArgs := []string{"-v", target + ":" + containerScanPath + ":ro"}
85		if opts.CacheDir != "" {
86			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
87		}
88		engineArgs = append(engineArgs, "-w", containerScanPath)
89		// Inside the container the paths are Linux ones, whatever the host is.
90		return containerRun{Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, afterOptions(files)...)}.cmd()
91	}
92	
93	// afterOptions is files, preceded by the end of the options ("--", which Go's
94	// flag package honors) when one of them starts with "-": a file named
95	// -cache=x.yaml would otherwise be read as an option (DEVDESK-763). kubeconform
96	// reports a file under the name it was given, so the findings keep it. Ordinary
97	// names get no "--".
98	func afterOptions(files []string) []string {
99		for _, f := range files {
100			if strings.HasPrefix(f, "-") {
101				return append([]string{"--"}, files...)
102			}
103		}
104		return files
105	}
106	
107	// kubeconformFlags are the options every validation run shares, raw files or
108	// rendered input.
109	func kubeconformFlags(tool ToolSpec, opts KubeconformOptions) []string {
110		// The user's flags first: there is no subcommand, and Go's flag package
111		// stops at the first positional argument.
112		flags := append(append([]string{}, tool.Args...), "-output", "json", "-strict")
113		if opts.KubernetesVersion != "" {
114			flags = append(flags, "-kubernetes-version", opts.KubernetesVersion)
115		}
116		if opts.CacheDir != "" {
117			cache := opts.CacheDir
118			if tool.Source == ToolSourceContainer {
119				cache = kubeconformCacheMount
120			}
121			flags = append(flags, "-cache", cache)
122		}
123		return flags
124	}
