214	// kubeconformFailure tells a run that found problems from one that failed.
215	// kubeconform exits 1 for both; what separates them is whether it wrote its
216	// JSON report.
217	func kubeconformFailure(out []byte, err error) error {
218		if err == nil {
219			return nil
220		}
221		var exitErr *exitError
222		if errors.As(err, &exitErr) && exitErr.Code == 1 && looksLikeJSON(out) {
223			return nil
224		}
225		return err
226	}
