// IsManifest reports whether any document of a YAML file has an apiVersion
// and a kind at its top level. A file that does not parse is not one: it
// cannot be applied either, but saying so is a linter's job, and the file may
// well not be meant for Kubernetes at all.
func IsManifest(content []byte) bool {
	dec := yaml.NewDecoder(bytes.NewReader(content))
	for {
		var doc map[string]any
		err := dec.Decode(&doc)
		if errors.Is(err, io.EOF) {
			return false
		}
		if err != nil {
			return false
		}
		if _, ok := doc["apiVersion"].(string); !ok {
			continue
		}
		if _, ok := doc["kind"].(string); ok {
			return true
		}
	}
}

// KustomizationFile returns the name of dir's Kustomize file, or "" when dir
// is not a Kustomize root.
func KustomizationFile(dir string) string {
	if p := kustomizationIn(dir); p != "" {
		return filepath.Base(p)
	}
	return ""
}

// kustomizationIn returns the path of dir's Kustomize file, or "".
func kustomizationIn(dir string) string {
	for _, name := range kustomizationFiles {
		p := filepath.Join(dir, name)
		if fileExists(p) {
			return p
		}
	}
	return ""
}

// kustomizationRefs are the fields through which one root pulls in another.
type kustomizationRefs struct {
	Resources  []string `yaml:"resources"`
	Bases      []string `yaml:"bases"`
	Components []string `yaml:"components"`
}

// leaves drops every Kustomize root another one references. A reference that

// Scan runs its stages concurrently against one runner, so a test says what
// each stage answers rather than what the next call answers.

type stageReply struct {
	stdout string
	err    error
}

// stageOf names the stage an invocation belongs to, from the invocation alone —
// which is the only thing the runner sees.
//
// "secret" and "trivy-secret" are separate: secret scanning is the one option
// served by both tools, Gitleaks over git history and Trivy over the target's
// content, and only Trivy's half applies to an image.
func stageOf(tc toolCmd) string {
	s := tc.String()
	switch {
	case strings.Contains(s, "--scanners license"):
		return "license"
	case strings.Contains(s, "--scanners misconfig"):
		return "misconfig"
	case strings.Contains(s, "--scanners secret"):
		return "trivy-secret"
	case strings.HasPrefix(s, "gitleaks"):
		return "secret"
	case strings.Contains(s, "-output json -strict"):
		return "k8s-schema"
	default:
		return "vuln"
	}
}

func byStage(t *testing.T, replies map[string]stageReply) *scriptedRunner {
	t.Helper()
	r := &scriptedRunner{}
	r.reply = func(tc toolCmd) ([]byte, error) {
		stage := stageOf(tc)
		reply, scripted := replies[stage]
		if !scripted {
			t.Errorf("the %s stage ran although nothing was scripted for it: %s", stage, tc)
		}
		return []byte(reply.stdout), reply.err
	}
	useRunner(t, r)
	return r
	}
	sort.Strings(seen)
	return seen
}

// binaries is a report in which these tools run from a binary on PATH, and
// every other tool is missing.
func binaries(ids ...ToolID) Report {
	r := Report{Tools: map[ToolID]ToolStatus{}, EngineAvailable: true}
	for _, id := range ids {
		tool, _ := ToolByID(id)
		r.Tools[id] = ToolStatus{Available: true, Source: ToolSourceBinary, Image: tool.DefaultImage}
	}
	return r
}

// without is the report with one tool gone. The map is copied: a report is a
// value, and a test that removes a tool must not remove it from another's.
func (r Report) without(id ToolID) Report {
	tools := make(map[ToolID]ToolStatus, len(r.Tools))
	for k, v := range r.Tools {
		tools[k] = v
	}
	delete(tools, id)
	r.Tools = tools
	return r
}

func everyTool() Report { return binaries(ToolTrivy, ToolGitleaks) }

// categories turns these categories on, each with its default tools, and
// every other one off.
func categories(ids ...CategoryID) config.ScanCategories {
	c := config.DefaultScanCategories()
	c.Vuln.Enabled, c.Secret.Enabled = false, false
	for _, id := range ids {
		c.Category(string(id)).Enabled = true
	}
	return c
}

// scanFor asks for these categories and nothing else.
func scanFor(ids ...CategoryID) ScanOptions { return ScanOptions{Categories: categories(ids...)} }

// k8sSchema is Misconfiguration with kubeconform and its renderers ticked and
// Trivy not: the schema stage alone.
func k8sSchema() ScanOptions {
	c := categories()
	c.Misconfig = config.CategoryConfig{Enabled: true,
		Tools: []string{config.ToolKubeconform, config.ToolHelm, config.ToolKustomize}}
	return ScanOptions{Categories: c}
}

func everyStage() ScanOptions {
	return scanFor(CategoryIDVuln, CategoryIDSecret, CategoryIDLicense, CategoryIDMisconfig)
}

