// ── The limit: symbolic links and `..` ───────────────────────────────────────

func TestVetOverlayDoesNotFollowASymbolicLinkOutOfTheRoot(t *testing.T) {
	outside := t.TempDir()
	writeFile(t, filepath.Join(outside, "kustomization.yaml"), "resources:\n  - "+q(loopbackURL)+"\n")
