// ── localRef ─────────────────────────────────────────────────────────────────

func TestLocalRefAcceptsOnlyWhatCanNameAPathOfTheRepository(t *testing.T) {
	accepted := []string{
		"base", "../base", "./x.yaml", "v1.2/base", "./github.com/o/r", "a b/c.yaml", "x.yaml", "../../notes/infra.yaml",
