				t.Errorf("localRef(%q) = %v, %q, want true and no reason", ref, ok, reason)
			}
		})
	}
	refused := []string{
		"http://127.0.0.1:8080/x.yaml", "https://127.0.0.1/x.yaml", "http://localhost:9/x.yaml", "http://[::1]:9/x.yaml",
