type gateKind int

const (
	gateOK gateKind = iota
	gateRemote
	gateUnchecked
)

type gateVerdict struct {
	Kind                     gateKind
	File, Field, Ref, Reason string
}
type gateLimits struct {
	Depth, Visited        int
	FileBytes, TotalBytes int64
}

var defaultGateLimits = gateLimits{Depth: 16, Visited: 256, FileBytes: 4 << 20, TotalBytes: 32 << 20}

func localRef(ref string) (bool, string) {
	if ref == "" {
		return false, "empty"
	}
	for _, r := range ref {
		if r < 0x20 || r == 0x7f {
			return false, "control"
		}
	}
	if strings.ContainsAny(ref, ":@?") {
		return false, "scheme"
	}
	if strings.HasPrefix(ref, "/") || strings.HasPrefix(ref, `\`) {
		return false, "absolute"
	}
	if first, _, _ := strings.Cut(ref, "/"); strings.EqualFold(first, "github.com") {
		return false, "github"
	}
	return true, ""
}

func readGateYAML(file string, maxBytes int64) (*yaml.Node, string) {
	info, err := os.Stat(file)
	if err != nil || !info.Mode().IsRegular() {
		return nil, "not a readable regular file"
	}
	if info.Size() > maxBytes {
		return nil, "too big"
	}
	data, err := os.ReadFile(file) //nolint:gosec // test scaffolding
	if err != nil {
		return nil, "unreadable"
	}
	return parseGateYAML(data)
}

func parseGateYAML(data []byte) (*yaml.Node, string) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var doc yaml.Node
	if err := dec.Decode(&doc); err != nil {
		return nil, "invalid YAML"
	}
	var second yaml.Node
	if err := dec.Decode(&second); !errors.Is(err, io.EOF) {
		return nil, "several documents"
	}
	if len(doc.Content) != 1 || doc.Content[0].Kind != yaml.MappingNode {
		return nil, "not a mapping"
	}
	if why := walkGate(doc.Content[0]); why != "" {
		return nil, why
	}
	return doc.Content[0], ""
}

func walkGate(n *yaml.Node) string {
	if n.Anchor != "" || n.Kind == yaml.AliasNode {
		return "anchor or alias"
	}
	if n.Style&yaml.TaggedStyle != 0 {
		return "explicit tag"
	}
	if n.Kind == yaml.MappingNode {
		var seen []string
		for i := 0; i+1 < len(n.Content); i += 2 {
			k := n.Content[i]
			if k.Tag == "!!merge" || k.Value == "<<" && k.Style == 0 {
				return "merge key"
			}
			for _, r := range k.Value {
				if r > 0x7e {
					return "non ASCII key"
				}
			}
			for _, s := range seen {
				if strings.EqualFold(s, k.Value) {
					return "duplicate key"
				}
			}
			seen = append(seen, k.Value)
			if why := walkGate(k); why != "" {
				return why
			}
			if why := walkGate(n.Content[i+1]); why != "" {
				return why
			}
		}
		return ""
	}
	for _, c := range n.Content {
		if why := walkGate(c); why != "" {
			return why
		}
	}
	return ""
}

type gateState struct {
	ctx     context.Context
	root    string
	lim     gateLimits
	visited map[string]bool
	total   int64
}

func vetOverlay(ctx context.Context, root, overlay string, lim gateLimits) gateVerdict {
	r, err := filepath.EvalSymlinks(root)
	if err != nil {
		return gateVerdict{Kind: gateUnchecked, Reason: "root"}
	}
	s := &gateState{ctx: ctx, root: r, lim: lim, visited: map[string]bool{}}
