	if v := c.listField(n, field, "files", false, func(_ int, f string, e *yaml.Node) gateVerdict {
		value, ok := str(e)
		if !ok {
			return unchecked(c.file, "not a string")
		}
		return c.filesEntry(f, value)
	}); v.Kind != gateOK {
		return v
	}
	if v := c.listField(n, field, "envs", false, nil); v.Kind != gateOK {
		return v
	}
	return c.strField(n, field, "env", false)
}

func (c gateRefCtx) helm(m *yaml.Node, base string) gateVerdict {
	if g := get(m, "helmGlobals"); g != nil && g.Kind == yaml.MappingNode {
		for _, k := range []string{"chartHome", "configHome"} {
			if v := c.strField(g, join(base, "helmGlobals"), k, false); v.Kind != gateOK {
				return v
			}
		}
	}
	if v := c.listField(m, base, "helmCharts", false, func(_ int, field string, n *yaml.Node) gateVerdict {
		return c.helmChart(n, field)
	}); v.Kind != gateOK {
		return v
	}
	return c.listField(m, base, "helmChartInflationGenerator", false, func(_ int, field string, n *yaml.Node) gateVerdict {
		for _, k := range []string{"chartRepoUrl", "helmBin"} {
			if v := get(n, k); v != nil && v.Value != "" {
				return gateVerdict{Kind: gateRemote, File: c.file, Field: join(field, k), Ref: v.Value, Reason: "helm"}
			}
		}
		if v := get(n, "extraArgs"); v != nil && len(v.Content) > 0 {
			return gateVerdict{Kind: gateRemote, File: c.file, Field: join(field, "extraArgs"), Reason: "helm"}
		}
		return gateVerdict{}
	})
}

func (c gateRefCtx) helmChart(n *yaml.Node, field string) gateVerdict {
	if v := get(n, "repo"); v != nil && v.Value != "" {
		return gateVerdict{Kind: gateRemote, File: c.file, Field: join(field, "repo"), Ref: v.Value, Reason: "helm"}
	}
	for _, k := range []string{"valuesFile", "chartHome"} {
		if v := c.strField(n, field, k, false); v.Kind != gateOK {
			return v
		}
	}
	return c.listField(n, field, "additionalValuesFiles", false, nil)
}

func (c gateRefCtx) plugins(m *yaml.Node, key string) gateVerdict {
	return c.listField(m, "", key, false, func(_ int, field string, n *yaml.Node) gateVerdict {
		value, ok := str(n)
		if !ok {
			return unchecked(c.file, "not a string")
		}
		if strings.Contains(value, "\n") {
			cfg, why := parseGateYAML([]byte(value))
			if why != "" {
				return unchecked(c.file, why)
			}
			return c.pluginConfig(cfg, field+".")
		}
		if ok, _ := localRef(value); !ok {
			return c.check(field, value, false)
		}
		p, inside := c.s.within(filepath.Join(c.dir, filepath.FromSlash(value)))
		if !inside {
			return unchecked(c.file, "outside the limit")
		}
		info, err := os.Stat(p)
		switch {
		case err != nil:
			return gateVerdict{}
		case info.IsDir():
			return c.s.dir(p, c.depth+1)
		}
		rel := c.s.rel(p)
		if v, bad := c.s.charge(p); bad {
			return v
		}
		cfg, why := readGateYAML(p, c.s.lim.FileBytes)
		if why != "" {
			return unchecked(rel, why)
		}
		return gateRefCtx{s: c.s, dir: filepath.Dir(p), file: rel, depth: c.depth}.pluginConfig(cfg, "")
	})
}

func (c gateRefCtx) pluginConfig(cfg *yaml.Node, prefix string) gateVerdict {
	if v := get(cfg, "apiVersion"); v == nil || v.Value != "builtin" {
		return unchecked(c.file, "not builtin")
	}
	if md := get(cfg, "metadata"); md != nil {
		if an := get(md, "annotations"); an != nil {
			for _, k := range []string{"config.kubernetes.io/function", "config.k8s.io/function"} {
				if get(an, k) != nil {
					return unchecked(c.file, "function")
				}
			}
		}
	}
	kind := ""
	if v := get(cfg, "kind"); v != nil {
		kind = v.Value
	}
	p := strings.TrimSuffix(prefix, ".")
	f := func(k string) string {
		if prefix == "" {
			return k
		}
		return prefix + k
	}
	switch kind {
	case "ConfigMapGenerator", "SecretGenerator":
		return c.genArgs(cfg, p)
	case "PatchTransformer", "PatchJson6902Transformer":
		return c.strField(cfg, p, "path", false)
	case "PatchStrategicMergeTransformer":
		return c.listField(cfg, p, "paths", false, nil)
	case "ReplacementTransformer":
		return c.listPaths(cfg, p, "replacements")
	case "ValueAddTransformer":
		return c.strField(cfg, p, "targetFilePath", false)
	case "HelmChartInflationGenerator":
		if v := get(cfg, "repo"); v != nil && v.Value != "" {
			return gateVerdict{Kind: gateRemote, File: c.file, Field: f("repo"), Ref: v.Value, Reason: "helm"}
		}
		for _, k := range []string{"valuesFile", "chartHome"} {
			if v := c.strField(cfg, p, k, false); v.Kind != gateOK {
				return v
			}
		}
		return gateVerdict{}
	}
	return unchecked(c.file, "unknown plugin kind")
}
